def ci(lo, hi, d=2):
    return f"({fmt(lo, d)}, {fmt(hi, d)})"


def tci(xb, s, n, c, d=2):
    t = tstar(c, n - 1); m = t * s / math.sqrt(n); return ci(xb - m, xb + m, d)


def zci_mean(xb, s, n, c, d=2):
    m = ZSTAR[c] * s / math.sqrt(n); return ci(xb - m, xb + m, d)


def tp(t, df, alt):
    return {"gt": float(st.t.sf(t, df)), "lt": float(st.t.cdf(t, df)), "ne": float(2 * st.t.sf(abs(t), df))}[alt]


# computed values used below
P_T19_20 = tp(1.9, 20, "gt")
P_T2_35 = tp(-2.0, 35, "ne")
