def build():
    for u, k, lv, prompt, key, wrongs, step, chk in ROWS:
        check = {"kind": "expr", "expr": chk, "no_print_check": "mc fill"} if isinstance(chk, str) else chk
        MC(u, k, lv, prompt, key, wrongs, [step] if isinstance(step, str) else step,
           family=f"{PREFIX[u]}_s{k:02d}_mcfill", std=STD[u][k], check=check)
